    font-weight: bold;
    font-size: 13px;
    margin: 10px 0 4px 0;
    text-indent: 0;
  }

  table.feed-table {
    width: 100%;
    border-collapse: collapse;
    margin: 4px 0;
    font-size: 9.5px;
  }

  table.feed-table td {
    padding: 1px 0;
    vertical-align: bottom;
  }

  .dotted-leader {
    border-bottom: 1px dotted #000;
  }

  ul.clean-list {
    list-style: none;
    padding-left: 0;
    margin: 0 0 5px 0;
